import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.sql.Savepoint;
import java.sql.Statement;

public class TransactionManagerDemo {
    public void executeBusinessLogic(String dbUrl, String user, String pass) {
        try (Connection conn = DriverManager.getConnection(dbUrl, user, pass)) {
            conn.setAutoCommit(false); // Begin transaction

            try (Statement stmt = conn.createStatement()) {
                stmt.executeUpdate("INSERT INTO accounts (id, balance) VALUES (1, 500)");

                // Set a savepoint after the first operation
                Savepoint sp1 = conn.setSavepoint("BeforeRiskyOperation");

                try {
                    stmt.executeUpdate("UPDATE inventory SET stock = stock - 1 WHERE id = 99");
                } catch (SQLException e) {
                    // Rollback only to the savepoint, preserving the initial insert
                    conn.rollback(sp1);
                    conn.releaseSavepoint(sp1);
                }

                // Finalize the transaction
                conn.commit();
            } catch (Exception e) {
                // Total failure: rollback everything
                conn.rollback();
                throw e;
            }
        } catch (SQLException e) {
            // Handle connection or fatal database errors
            e.printStackTrace();
        }
    }
}
